// Thai Industrial Standard 620-2533 (TIS-620) and its Windows superset CP874.
// See <https://www.unicode.org/Public/MAPPINGS/ISO8859/8859-11.TXT> and
// <https://www.unicode.org/Public/MAPPINGS/VENDORS/MICSFT/WINDOWS/CP874.TXT>
use phf::phf_map;

pub(crate) fn get(code: u8) -> Option<&'static str> {
    if code < 0x80 {
        return super::win_ansi::get(code);
    }

    TIS_620.get(&code).copied()
}

